/**
 * Admin panel for managing access codes and viewing signup stats.
 *
 * Shows a stats bar, a create-code form, a filterable table of codes,
 * and pagination.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useCedrosLoginAdminClientContext } from '../../hooks/useCedrosLoginAdminClientContext';
import { AdminUserApiClient } from '../../utils/adminUserApi';
import type {
  AdminAccessCode,
  AdminSignupStats,
} from '../../utils/adminUserApi';

// =============================================================================
// Props
// =============================================================================

export interface AdminAccessCodesProps {
  className?: string;
}

type TabId = 'all' | 'limited' | 'user_invite';

const PAGE_SIZE = 20;

// =============================================================================
// Helpers
// =============================================================================

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return iso;
  }
}

function codeIsExpired(code: AdminAccessCode): boolean {
  return !!code.expiresAt && new Date(code.expiresAt) < new Date();
}

function codeIsExhausted(code: AdminAccessCode): boolean {
  return code.maxUses !== null && code.currentUses >= code.maxUses;
}

function codeStatus(code: AdminAccessCode): string {
  if (codeIsExpired(code)) return 'expired';
  if (codeIsExhausted(code)) return 'exhausted';
  return 'active';
}

// =============================================================================
// Component
// =============================================================================

/**
 * Admin access codes management panel.
 *
 * Inputs: className
 * Outputs: CRUD for access codes; displays signup stats
 * Errors: displayed inline
 */
export function AdminAccessCodes({ className = '' }: AdminAccessCodesProps) {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const apiClient = useMemo(
    () =>
      new AdminUserApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  // ---- list state ----
  const [activeTab, setActiveTab] = useState<TabId>('all');
  const [items, setItems] = useState<AdminAccessCode[]>([]);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  // ---- stats state ----
  const [stats, setStats] = useState<AdminSignupStats | null>(null);

  // ---- create form state ----
  const [newCode, setNewCode] = useState('');
  const [newMaxUses, setNewMaxUses] = useState('');
  const [newExpiry, setNewExpiry] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [createError, setCreateError] = useState<string | null>(null);
  const [createSuccess, setCreateSuccess] = useState(false);

  // ---- delete state ----
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const tabTypeMap: Record<TabId, string | undefined> = {
    all: undefined,
    limited: 'limited',
    user_invite: 'user_invite',
  };

  const fetchItems = useCallback(async () => {
    setIsLoading(true);
    setFetchError(null);
    try {
      const resp = await apiClient.listAccessCodes(PAGE_SIZE, offset, tabTypeMap[activeTab]);
      setItems(resp.items);
      setTotal(resp.total);
    } catch (err) {
      setFetchError(err instanceof Error ? err.message : 'Failed to load access codes');
    } finally {
      setIsLoading(false);
    }
  }, [apiClient, activeTab, offset]); // eslint-disable-line react-hooks/exhaustive-deps

  const fetchStats = useCallback(async () => {
    try {
      const s = await apiClient.getSignupStats();
      setStats(s);
    } catch {
      // Non-critical — stats bar just won't show
    }
  }, [apiClient]);

  useEffect(() => {
    fetchItems();
    fetchStats();
  }, [fetchItems, fetchStats]);

  // Reset offset when tab changes
  useEffect(() => {
    setOffset(0);
  }, [activeTab]);

  const handleCreate = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newCode.trim()) {
        setCreateError('Code is required.');
        return;
      }
      const maxUses = newMaxUses.trim() ? parseInt(newMaxUses, 10) : null;
      if (newMaxUses.trim() && (isNaN(maxUses as number) || (maxUses as number) < 1)) {
        setCreateError('Max uses must be a positive integer.');
        return;
      }
      const expiresAt = newExpiry.trim() ? new Date(newExpiry).toISOString() : undefined;

      setIsCreating(true);
      setCreateError(null);
      setCreateSuccess(false);
      try {
        await apiClient.createAccessCode(newCode.trim(), maxUses, expiresAt);
        setNewCode('');
        setNewMaxUses('');
        setNewExpiry('');
        setCreateSuccess(true);
        fetchItems();
        fetchStats();
      } catch (err) {
        setCreateError(err instanceof Error ? err.message : 'Failed to create code');
      } finally {
        setIsCreating(false);
      }
    },
    [apiClient, newCode, newMaxUses, newExpiry, fetchItems, fetchStats]
  );

  const handleDelete = useCallback(
    async (id: string) => {
      setDeletingId(id);
      setDeleteError(null);
      try {
        await apiClient.deleteAccessCode(id);
        setItems((prev) => prev.filter((c) => c.id !== id));
        setTotal((prev) => prev - 1);
      } catch (err) {
        setDeleteError(err instanceof Error ? err.message : 'Failed to delete code');
      } finally {
        setDeletingId(null);
      }
    },
    [apiClient]
  );

  const totalPages = Math.ceil(total / PAGE_SIZE);
  const currentPage = Math.floor(offset / PAGE_SIZE) + 1;

  return (
    <div className={`cedros-admin-access-codes ${className}`}>
      <div className="cedros-admin-access-codes__header">
        <h2 className="cedros-admin-access-codes__title">Access Codes</h2>
        <button
          type="button"
          className="cedros-admin__stats-bar-refresh"
          onClick={() => { fetchItems(); fetchStats(); }}
          disabled={isLoading}
          title="Refresh"
          aria-label="Refresh list"
        >
          {isLoading ? '...' : '↻'}
        </button>
      </div>

      {/* ---- Stats bar ---- */}
      {stats && (
        <div className="cedros-admin-access-codes__stats-bar" aria-label="Signup statistics">
          <span className="cedros-admin-access-codes__stat">
            <strong>Signups this {stats.period}:</strong>{' '}
            {stats.count}
            {stats.limit !== null ? ` / ${stats.limit}` : ''}
          </span>
          <span className="cedros-admin-access-codes__stat">
            <strong>Period start:</strong> {formatDate(stats.periodStart)}
          </span>
        </div>
      )}

      {/* ---- Create form ---- */}
      <section className="cedros-admin-access-codes__create-section" aria-label="Create access code">
        <h3 className="cedros-admin-access-codes__section-title">Create Code</h3>
        <form
          className="cedros-admin-access-codes__create-form"
          onSubmit={handleCreate}
          aria-label="Create access code form"
        >
          <div className="cedros-form-field cedros-form-field--inline">
            <label htmlFor="ac-code" className="cedros-label">Code</label>
            <input
              id="ac-code"
              type="text"
              className="cedros-input"
              value={newCode}
              onChange={(e) => { setNewCode(e.target.value); setCreateError(null); setCreateSuccess(false); }}
              placeholder="e.g. BETA2025"
              disabled={isCreating}
              required
            />
          </div>
          <div className="cedros-form-field cedros-form-field--inline">
            <label htmlFor="ac-max-uses" className="cedros-label">
              Max Uses <span className="cedros-optional">(blank = unlimited)</span>
            </label>
            <input
              id="ac-max-uses"
              type="number"
              className="cedros-input"
              value={newMaxUses}
              onChange={(e) => setNewMaxUses(e.target.value)}
              placeholder="e.g. 100"
              min="1"
              disabled={isCreating}
            />
          </div>
          <div className="cedros-form-field cedros-form-field--inline">
            <label htmlFor="ac-expiry" className="cedros-label">
              Expiry <span className="cedros-optional">(optional)</span>
            </label>
            <input
              id="ac-expiry"
              type="date"
              className="cedros-input"
              value={newExpiry}
              onChange={(e) => setNewExpiry(e.target.value)}
              disabled={isCreating}
            />
          </div>
          <button
            type="submit"
            className="cedros-button cedros-button-primary cedros-button-md"
            disabled={isCreating}
            aria-busy={isCreating}
          >
            {isCreating ? 'Creating...' : 'Create'}
          </button>
        </form>
        {createError && (
          <div className="cedros-admin-error" role="alert">{createError}</div>
        )}
        {createSuccess && !createError && (
          <div className="cedros-admin-success" role="status">Code created.</div>
        )}
      </section>

      {/* ---- Filter tabs ---- */}
      <div className="cedros-admin-tabs cedros-admin-tabs--line" role="tablist">
        {(['all', 'limited', 'user_invite'] as TabId[]).map((tab) => (
          <button
            key={tab}
            type="button"
            className={`cedros-admin-tab ${activeTab === tab ? 'cedros-admin-tab-active' : ''}`}
            onClick={() => setActiveTab(tab)}
            aria-selected={activeTab === tab}
            role="tab"
          >
            {tab === 'all' ? 'All' : tab === 'limited' ? 'Limited' : 'User Invite'}
          </button>
        ))}
      </div>

      {deleteError && (
        <div className="cedros-admin-error" role="alert">{deleteError}</div>
      )}

      {fetchError && (
        <div className="cedros-admin-access-codes--error">
          <p className="cedros-admin-error">{fetchError}</p>
          <button
            type="button"
            className="cedros-button cedros-button-outline cedros-button-sm"
            onClick={fetchItems}
          >
            Retry
          </button>
        </div>
      )}

      {/* ---- Code table ---- */}
      {!fetchError && (
        <div role="tabpanel">
          {isLoading && items.length === 0 ? (
            <div className="cedros-admin-access-codes--loading">
              <span className="cedros-admin-loading-indicator" />
              <span className="cedros-admin-loading-text">Loading...</span>
            </div>
          ) : items.length === 0 ? (
            <div className="cedros-admin-empty-message">No access codes found.</div>
          ) : (
            <>
              <div
                className="cedros-admin-list-table cedros-admin-access-codes__table"
                role="table"
                aria-label="Access codes"
              >
                <div className="cedros-admin-list-thead" role="row">
                  <div className="cedros-admin-list-th" role="columnheader">Code</div>
                  <div className="cedros-admin-list-th" role="columnheader">Type</div>
                  <div className="cedros-admin-list-th" role="columnheader">Uses</div>
                  <div className="cedros-admin-list-th" role="columnheader">Created By</div>
                  <div className="cedros-admin-list-th" role="columnheader">Created</div>
                  <div className="cedros-admin-list-th" role="columnheader">Expires</div>
                  <div className="cedros-admin-list-th" role="columnheader">Status</div>
                  <div className="cedros-admin-list-th" role="columnheader">
                    <span className="cedros-sr-only">Actions</span>
                  </div>
                </div>
                {items.map((code) => {
                  const status = codeStatus(code);
                  const usesLabel =
                    code.maxUses !== null
                      ? `${code.currentUses} / ${code.maxUses}`
                      : `${code.currentUses}`;
                  return (
                    <div key={code.id} className="cedros-admin-list-row" role="row">
                      <div className="cedros-admin-list-td" role="cell">
                        <code className="cedros-admin-access-codes__code">{code.code}</code>
                      </div>
                      <div className="cedros-admin-list-td" role="cell">{code.codeType}</div>
                      <div className="cedros-admin-list-td" role="cell">{usesLabel}</div>
                      <div className="cedros-admin-list-td" role="cell">
                        {code.createdByEmail ?? '—'}
                      </div>
                      <div className="cedros-admin-list-td" role="cell">
                        {formatDate(code.createdAt)}
                      </div>
                      <div className="cedros-admin-list-td" role="cell">
                        {code.expiresAt ? formatDate(code.expiresAt) : '—'}
                      </div>
                      <div className="cedros-admin-list-td" role="cell">
                        <span className={`cedros-admin-access-codes__status cedros-admin-access-codes__status--${status}`}>
                          {status.charAt(0).toUpperCase() + status.slice(1)}
                        </span>
                      </div>
                      <div className="cedros-admin-list-td" role="cell">
                        <button
                          type="button"
                          className="cedros-button cedros-button-danger cedros-button-sm"
                          onClick={() => handleDelete(code.id)}
                          disabled={deletingId === code.id}
                          aria-label={`Delete code ${code.code}`}
                        >
                          {deletingId === code.id ? '...' : 'Delete'}
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>

              {totalPages > 1 && (
                <div className="cedros-admin-pagination">
                  <button
                    type="button"
                    className="cedros-button cedros-button-outline cedros-button-sm"
                    onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}
                    disabled={currentPage <= 1}
                  >
                    Previous
                  </button>
                  <span className="cedros-admin-page-info">
                    Page {currentPage} of {totalPages} ({total} total)
                  </span>
                  <button
                    type="button"
                    className="cedros-button cedros-button-outline cedros-button-sm"
                    onClick={() => setOffset(offset + PAGE_SIZE)}
                    disabled={currentPage >= totalPages}
                  >
                    Next
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}
